	laneRoot: string;
	receiptRoot: string;
}): Promise<WitnessRealAppRun> {
	const app = apps.find((candidate) => candidate.app === 'angular-realworld');
	if (app === undefined) throw new Error('Angular RealWorld Witness specification is absent');
	return await executeRun(app, options.lane, options.pass, options);
}

export async function executeReactBoilerplateWitnessRun(options: {
	lane: Lane;
	pass: 1 | 2;
	laneRoot: string;
	receiptRoot: string;
}): Promise<WitnessRealAppRun> {
	const app = apps.find((candidate) => candidate.app === 'react-boilerplate');
	if (app === undefined) throw new Error('React Boilerplate Witness specification is absent');
	return await executeRun(app, options.lane, options.pass, options);
}

export async function executeReactPapercupsWitnessRun(options: {
	lane: Lane;
	pass: 1 | 2;
	laneRoot: string;
	receiptRoot: string;
}): Promise<WitnessRealAppRun> {
	const app = apps.find((candidate) => candidate.app === 'papercups');
	if (app === undefined) throw new Error('Papercups Witness specification is absent');
	return await executeRun(app, options.lane, options.pass, {
		...options,
		serviceWorkerPolicy: 'zero',
	});
}

/**
 * Same runtime check as the zero-worker checkpoint, for an application whose
 * own code calls `register()` and whose registration the browser context
 * refuses: nothing may be registered, controlling, cached, or emitting worker
 * lifecycle events at this point in the journey.
 */
async function blockedServiceWorkerCheckpoint(
	lifecycle: JourneyLifecycle,
	phase: 'before-interactions' | 'after-interactions' | 'after-online-reload',
): Promise<{
	phase: typeof phase;
	state: 'timeout';
	registrations: 0;
	controller: null;
	cacheNames: [];
	workerEvents: [];
}> {
	return await zeroServiceWorkerCheckpoint(lifecycle, phase);
}

export async function executeReactHospitalrunWitnessRun(options: {
	lane: Lane;
	pass: 1 | 2;
	laneRoot: string;
	receiptRoot: string;
}): Promise<WitnessRealAppRun> {
	const app = apps.find((candidate) => candidate.app === 'react-hospitalrun');
	if (app === undefined) throw new Error('HospitalRun Witness specification is absent');
	return await executeRun(app, options.lane, options.pass, options);
}

/**
 * The Memos Witness specification, reachable so its declared inventories,
 * probes and lane bindings can be checked against the receipt schema that
 * enforces them without launching a browser.
 */
export function reactMemosWitnessSpec(): AppSpec {
	const app = apps.find((candidate) => candidate.app === 'react-memos');
	if (app === undefined) throw new Error('Memos Witness specification is absent');
	return app;
}

export async function executeReactMemosWitnessRun(options: {
	lane: Lane;
	pass: 1 | 2;
	laneRoot: string;
	receiptRoot: string;
}): Promise<WitnessRealAppRun> {
	return await executeRun(reactMemosWitnessSpec(), options.lane, options.pass, options);
}

export async function executeReactLinkfreeWitnessRun(options: {
	lane: Lane;
	pass: 1 | 2;
	laneRoot: string;
	receiptRoot: string;
}): Promise<WitnessRealAppRun> {
	const app = apps.find((candidate) => candidate.app === 'react-linkfree');
	if (app === undefined) throw new Error('LinkFree Witness specification is absent');
	return await executeRun(app, options.lane, options.pass, options);
}

/**
 * factoriolab ships no service worker in either lane and never calls
 * `register()`, so the run is executed under the zero-worker policy: the
 * browser context still allows registration, and the journey is required to
 * observe nothing registered, controlling, cached or requested at each of its
 * three checkpoints.
 */
export async function executeAngularFactoriolabWitnessRun(options: {
	lane: Lane;
	pass: 1 | 2;
	laneRoot: string;
	receiptRoot: string;
}): Promise<WitnessRealAppRun> {
	const app = apps.find((candidate) => candidate.app === 'angular-factoriolab');
	if (app === undefined) throw new Error('factoriolab Witness specification is absent');
	return await executeRun(app, options.lane, options.pass, {
		...options,
		serviceWorkerPolicy: 'zero',
	});
}

/**
 * The jira-clone Witness specification, reachable so its declared inventories,
 * probes and seams can be checked against the receipt schema that enforces them
 * without launching a browser.
 */
export function angularJiraCloneWitnessSpec(): AppSpec {
	const app = apps.find((candidate) => candidate.app === 'angular-jira-clone');
	if (app === undefined) throw new Error('jira-clone Witness specification is absent');
	return app;
}

/**
 * jira-clone ships no service worker in either lane and never calls
 * `register()`, so the run is executed under the zero-worker policy: the
 * browser context still allows registration, and the journey is required to
 * observe nothing registered, controlling, cached or requested at each of its
 * three checkpoints.
 */
export async function executeAngularJiraCloneWitnessRun(options: {
	lane: Lane;
	pass: 1 | 2;
	laneRoot: string;
	receiptRoot: string;
}): Promise<WitnessRealAppRun> {
	return await executeRun(angularJiraCloneWitnessSpec(), options.lane, options.pass, {
		...options,
		serviceWorkerPolicy: 'zero',
	});
}

/**
 * The killedbygoogle v3 Witness specification, reachable so its declared
 * inventories, probes and lane bindings can be checked against the receipt
 * schema that enforces them without launching a browser.
 */
export function nextKilledbygoogleV3WitnessSpec(): AppSpec {
	const app = apps.find((candidate) => candidate.app === NEXT_KILLEDBYGOOGLE_V3_APP);
	if (app === undefined) throw new Error('KilledByGoogle v3 Witness specification is absent');
	return app;
}

const SUPER_PRODUCTIVITY_JOURNEY = WITNESS_ANGULAR_SUPER_PRODUCTIVITY_JOURNEY;

/** The migrated build record this proof serves, bound by the sha256 of its bytes. */
const SUPER_PRODUCTIVITY_BOUND_MIGRATED = ANGULAR_SUPER_PRODUCTIVITY_CANONICAL_RECEIPTS.find(
	(bound) => bound.lane === 'migrated',
);
if (SUPER_PRODUCTIVITY_BOUND_MIGRATED === undefined)
	throw new Error('Super Productivity bound migrated build record is absent');

const angularSuperProductivitySpec: AppSpec = {
	app: ANGULAR_SUPER_PRODUCTIVITY_APP,
	canonicalReceipt: SUPER_PRODUCTIVITY_BOUND_MIGRATED.path,
	/**
	 * The bound record publishes a top-level `digest` over its own content rather
	 * than an `integrity.canonicalDigest`, so the honest binding is the sha256 of
	 * its exact bytes — the same value the receipt schema binds it by.
	 */
	canonicalDigest: SUPER_PRODUCTIVITY_BOUND_MIGRATED.sha256,
	canonicalBinding: 'file-sha256',
	framework: 'angular',
	sources: {
		baseline: '.versionless/cache/angular-super-productivity-v2-13-15-baseline/dist-run2',
		migrated: '.versionless/stage/angular-super-productivity-v2-13-15-u18b/dist-25',
	},
	/**
	 * Deep-linked rather than opened bare. The bare document records its
	 * navigation as `#/`, which the router resolves through its `**` route onto
	 * the work view — a route the application does not declare, and one the
	 * receipt schema refuses as a recorded navigation. Asking for the declared
	 * route is what makes the recorded navigation a declared one.
	 */
	initialRoute: SUPER_PRODUCTIVITY_JOURNEY.initialRoute,
	viewport: SUPER_PRODUCTIVITY_JOURNEY.viewport,
	consoleErrorInventory: WITNESS_ANGULAR_SUPER_PRODUCTIVITY_CONSOLE_ERRORS,
	failedRequestInventory: WITNESS_ANGULAR_SUPER_PRODUCTIVITY_FAILED_REQUESTS,
	mockedNonLoopbackSeams: WITNESS_ANGULAR_SUPER_PRODUCTIVITY_LANE_SEAMS,
	renderedStyleProbes: WITNESS_ANGULAR_SUPER_PRODUCTIVITY_STYLE_PROBES,
	indexedDb: 'read-keys',
	/**
	 * The one seam either lane reaches for: the Roboto stylesheet the
	 * application's own `index.html` links. It is answered in-context with an
	 * empty body, so nothing leaves the machine and the request is still written
	 * down — and the glyphs never arrive, which is the typeface degradation the
	 * journey measures rather than hides.
	 */
	transport: async () => ({
		action: 'fulfill',
		status: 200,
		contentType: 'text/css',
		body: Buffer.alloc(0),
	}),
	journey: async (context, page, _transportEvidence, lifecycle) => {
		if (lifecycle.expectedServiceWorker !== null)
			throw new Error('Super Productivity journey received a service-worker expectation');
		const script = WITNESS_ANGULAR_SUPER_PRODUCTIVITY_SERVICE_WORKER.script;
		const checkpoints: WitnessRealServiceWorkerCheckpoint[] = [
			await realServiceWorkerCheckpoint(lifecycle, 'before-interactions', script),
		];
		const measuredRoutes: WitnessMeasuredScrollAbsence['routes'] = [];
		/**
		 * Taken at every stage. The application pins its drawer container to the
		 * viewport and scrolls its own inner panels, so a stage that started
		 * overflowing fails here rather than passing silently unexercised.
		 */
		const measure = async (stage: string): Promise<void> => {
			const extents = await lifecycle.viewportScroll();
			if (
				extents.clientHeight !== SUPER_PRODUCTIVITY_JOURNEY.viewport.height ||
				extents.scrollHeight > extents.clientHeight ||
				extents.scrollY !== 0
			)
				throw new Error(
					`Super Productivity stage overflows the viewport the receipt says it does not: ${stage} ${canonicalize(extents)}`,
				);
			measuredRoutes.push({
				route: stage,
				scrollHeight: extents.scrollHeight,
				clientHeight: extents.clientHeight,
			});
		};
		/** The application's own store, read for its keys and never its values. */
		const storeKeys = async (): Promise<string[]> =>
			witnessIndexedDbStringKeys(
				await lifecycle.indexedDbKeys(),
				WITNESS_ANGULAR_SUPER_PRODUCTIVITY_PERSISTENCE.databaseName,
				WITNESS_ANGULAR_SUPER_PRODUCTIVITY_PERSISTENCE.storeName,
			);
		const localKeys = async (): Promise<string[]> => {
			const keys = await lifecycle.browserStorageKeys();
			if (keys.sessionStorage.length !== 0)
				throw new Error(
					`Super Productivity wrote session storage the receipt says it does not: ${canonicalize(keys.sessionStorage)}`,
				);
			return [...keys.localStorage].sort();
		};
		/** The rendered task titles in document order, for legs (b) and (e). */
		const readOrder = async (): Promise<string[]> =>
			(await lifecycle.groupedText(SUPER_PRODUCTIVITY_JOURNEY.taskTitleProbe)).map(
				(group) => group.name,
			);
		/** The single icon the header's own global play button renders, for leg (c). */
		const readHeaderIcon = async (): Promise<string> => {
			const icons = (
				await lifecycle.groupedText(SUPER_PRODUCTIVITY_JOURNEY.timeTracking.iconProbe)
			).flatMap((group) => group.items);
			if (icons.length !== 1)
				throw new Error(
					`Super Productivity header play button rendered ${icons.length} icons, not one`,
				);
			return icons[0]!;
		};
		await page.trackEvents('click', 'input', 'keydown');

		// The application as it boots: the work view's own host tag — `work-view`,
		// not the component's file name — its two task lists, and no task in
		// either of them. Nothing has been seeded; this application starts empty.
		await context.expect.page.count(page, SUPER_PRODUCTIVITY_JOURNEY.hostTag, 1);
		await context.expect.page.count(
			page,
			SUPER_PRODUCTIVITY_JOURNEY.taskList,
			SUPER_PRODUCTIVITY_JOURNEY.taskLists,
		);
		await context.expect.page.count(page, SUPER_PRODUCTIVITY_JOURNEY.taskListTask, 0);
		const renderedStyles = await lifecycle.renderedStyles();
		const keysBeforeJourney = await storeKeys();
		const localStorageKeysBeforeJourney = await localKeys();
		await measure(`${SUPER_PRODUCTIVITY_JOURNEY.initialRoute} (before the create)`);

		// (a) The create. The add-task bar is configured `[isAddToBacklog]="false"`
		// in the work view's own template, so a title committed with Enter lands in
		// today's list rather than in the backlog — which is what the count below
		// is actually testing, and why it is asserted on `task-list task` rather
		// than on `task` anywhere in the document.
		await page.type(
			SUPER_PRODUCTIVITY_JOURNEY.addTaskInput,
			SUPER_PRODUCTIVITY_JOURNEY.taskTitleText,
			{ redact: false },
		);
		await page.press(SUPER_PRODUCTIVITY_JOURNEY.addTaskInput, 'Enter');
		await context.expect.page.count(page, SUPER_PRODUCTIVITY_JOURNEY.taskListTask, 1);
		await context.expect.page.text(
			page,
			SUPER_PRODUCTIVITY_JOURNEY.taskTitle,
			SUPER_PRODUCTIVITY_JOURNEY.taskTitleText,
		);
		await measure(`${SUPER_PRODUCTIVITY_JOURNEY.initialRoute} (after the create)`);

		// A second task, so leg (b) has a list to reorder. It lands below the
		// first, and that first-created-on-top order is where leg (b) begins.
		await page.type(
			SUPER_PRODUCTIVITY_JOURNEY.addTaskInput,
			SUPER_PRODUCTIVITY_JOURNEY.secondTaskTitleText,
			{ redact: false },
		);
		await page.press(SUPER_PRODUCTIVITY_JOURNEY.addTaskInput, 'Enter');
		await context.expect.page.count(page, SUPER_PRODUCTIVITY_JOURNEY.taskListTask, 2);
		const renderedOrderBefore = await readOrder();
		if (
			canonicalize(renderedOrderBefore) !==
