import { join } from 'pathe';
import { box, runBoxes } from '@async/witness';
import { joinURL } from 'ufo';
import { startStaticServer } from '../src/witness/real-app-run.ts';
import { createPlaywrightWitnessHost } from '../src/witness/playwright-host.ts';
import { witnessNodeFileSystem } from '../src/witness/node-filesystem.ts';

const root = '/Users/jacksm5pro/dev/open-source/versionless';
const chromium = join(root, '.versionless/cache/react-boilerplate-v4/ms-playwright/chromium_headless_shell-1208/chrome-headless-shell-mac-arm64/chrome-headless-shell');
const laneRoots = {
  baseline: join(root, '.versionless/cache/angular-super-productivity-v2-13-15-baseline/dist-run2'),
  migrated: join(root, '.versionless/stage/angular-super-productivity-v2-13-15-u18b/dist-25'),
} as const;
const lane = (process.argv[2] ?? 'migrated') as 'baseline'|'migrated';
const laneRoot = laneRoots[lane];
const staticServer = await startStaticServer(laneRoot, { profile: 'current-witness' });
const host = createPlaywrightWitnessHost({
  chromiumExecutable: chromium, contextProfile: 'current-witness',
  viewport: { width: 1280, height: 900 }, indexedDb: 'read-keys',
  transport: async () => ({ action: 'fulfill', status: 200, contentType: 'text/css', body: Buffer.alloc(0) }),
});
const out: Record<string, unknown> = {};
const countOf = async (page: any, ctx: any, sel: string): Promise<number> => {
  try { await ctx.expect.page.count(page, sel, -0); return 0; }
  catch { }
  // fall back: parse from a probe that expects 0
  try { await ctx.expect.page.count(page, sel, 0); return 0; }
  catch (e:any) { const m = String(e.message).match(/observed (\d+)/); return m ? Number(m[1]) : -1; }
};
const def = box(`probe-${lane}`, async (context) => {
  const page = await context.browser.visit(joinURL(staticServer.origin, '/#/work-view'));
  out.bootTaskList = await countOf(page, context, 'task-list');
  out.bootTaskListWrapper = await countOf(page, context, '.task-list-wrapper');
  out.bootBacklog = await countOf(page, context, 'backlog');
  out.bootCompletedHeading = await countOf(page, context, '.completed-tasks-heading');
  await page.trackEvents('click','input','keydown');
  await page.type('add-task-bar input', 'Probe task one', { redact: false });
  await page.press('add-task-bar input', 'Enter');
  await new Promise(r=>setTimeout(r,500));
  out.after1_taskList = await countOf(page, context, 'task-list');
  out.after1_task = await countOf(page, context, 'task-list task');
  await page.type('add-task-bar input', 'Probe task two', { redact: false });
  await page.press('add-task-bar input', 'Enter');
  await new Promise(r=>setTimeout(r,500));
  out.after2_taskList = await countOf(page, context, 'task-list');
  out.after2_task = await countOf(page, context, 'task-list task');
});
try {
  await runBoxes({ root: laneRoot, boxes: [{ file: join(laneRoot,'versionless-runtime.box.ts'), relativeFile:'versionless-runtime.box.ts', exportName:'default', box: def }], receiptDir: join(root,'.versionless/stage/_probe',lane), assertionTimeoutMs: 8000, fileSystem: witnessNodeFileSystem, browser: host.browser, headless: true });
} finally { await staticServer.close(); }
console.log(lane, JSON.stringify(out, null, 2));
EOF
